// Locale resolution and interpolation over the generated care catalog.
// The catalog itself is generated by tools/generate-care-i18n.mjs.
const catalog = require('./care-i18n.js');

let currentLocale = 'zh-CN';

function resolveLocale(value) {
  const normalized = String(value || '').toLowerCase();
  if (normalized.indexOf('zh') === 0) return 'zh-CN';
  if (normalized.indexOf('en') === 0) return 'en-US';
  return 'en-US';
}

function detectLocale() {
  try {
    const info = wx.getSystemInfoSync();
    return resolveLocale(info.language || info.Language);
  } catch (error) {
    return currentLocale;
  }
}

function setLocale(value) {
  currentLocale = resolveLocale(value);
  return currentLocale;
}

function getLocale() {
  return currentLocale;
}

function careText(key, params) {
  const locale = catalog.messages[currentLocale] || catalog.messages['en-US'] || {};
  const fallback = catalog.messages['en-US'] || {};
  let resolved = locale[key] !== undefined ? locale[key] : fallback[key];
  if (resolved === undefined) resolved = key;
  if (params) {
    Object.keys(params).forEach((name) => {
      resolved = resolved.split('{{' + name + '}}').join(String(params[name]));
    });
  }
  return resolved;
}

module.exports = {
  careText,
  setLocale,
  getLocale,
  resolveLocale,
  detectLocale,
  careLocales: catalog.locales,
};
